package com.geely.pipinstaller;
import android.content.*;import android.content.pm.*;import android.os.*;import java.util.*;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,manifest=Config.NONE,shadows={DashboardApiServiceTest.Platform.class})
public class DashboardApiServiceTest {
 @Implements(PlatformBridge.class) public static class Platform {static boolean value;static int reads;@Implementation protected void __constructor__(Context c){}@Implementation protected boolean enabled(){reads++;return value;}}
 private org.robolectric.android.controller.ServiceController<DashboardApiService> controller;private DashboardApiService service;private final List<Bundle> replies=new ArrayList<>();private Messenger api,reply;
 private void pkg(String name,int uid,String cert){PackageInfo info=new PackageInfo();info.packageName=name;info.applicationInfo=new ApplicationInfo();info.applicationInfo.packageName=name;info.applicationInfo.uid=uid;info.signatures=new Signature[]{new Signature(cert)};Shadows.shadowOf(RuntimeEnvironment.getApplication().getPackageManager()).installPackage(info);}
 @Before public void setup(){Platform.reads=0;Platform.value=false;PipService.state(RuntimeEnvironment.getApplication()).edit().clear().commit();pkg(RuntimeEnvironment.getApplication().getPackageName(),android.os.Process.myUid(),"aabb");pkg("vn.tht.ex2.car",10123,"aabb");pkg("untrusted.app",10124,"aabb");controller=Robolectric.buildService(DashboardApiService.class).create();service=controller.get();api=new Messenger(service.onBind(new Intent()));reply=new Messenger(new Handler(Looper.getMainLooper(),message->{replies.add(new Bundle(message.getData()));return true;}));}
 @After public void close(){controller.destroy();ShadowBinder.reset();}
 private Bundle send(int command,int uid,boolean refresh)throws Exception{Message message=Message.obtain(null,command);Bundle data=new Bundle();data.putString("request","test_request_123");data.putBoolean("refresh",refresh);message.setData(data);message.replyTo=reply;ShadowBinder.setCallingUid(uid);api.send(message);ShadowBinder.reset();Shadows.shadowOf(Looper.getMainLooper()).idle();return replies.get(replies.size()-1);}
 @Test public void unauthorizedCallerCannotReadStateOrStartInstaller()throws Exception{Bundle value=send(2,10124,false);assertFalse(value.getBoolean("accepted"));assertFalse(value.containsKey("enabled"));assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertEquals(0,Platform.reads);}
 @Test public void enableAndDisableUseOriginalServiceAndOnlyIdleStateIsVerified()throws Exception{Bundle value=send(2,10123,false);assertTrue(value.getBoolean("accepted"));assertTrue(value.getBoolean("busy"));assertFalse(value.getBoolean("verified"));assertEquals(PipService.ENABLE,Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService().getAction());PipService.state(service).edit().putBoolean("busy",false).putBoolean("pending",false).commit();Platform.value=true;value=send(1,10123,false);assertTrue(value.getBoolean("verified"));assertTrue(value.getBoolean("enabled"));value=send(3,10123,false);assertTrue(value.getBoolean("busy"));assertEquals(PipService.DISABLE,Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService().getAction());PipService.state(service).edit().putBoolean("busy",false).commit();Platform.value=false;value=send(1,10123,false);assertTrue(value.getBoolean("verified"));assertFalse(value.getBoolean("enabled"));}
 @Test public void trustedPackageWithDifferentCertificateCannotStartInstaller()throws Exception{pkg("vn.tht.ex2.car",10123,"ccdd");assertFalse(send(2,10123,false).getBoolean("accepted"));assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());}
 @Test public void staleQueuedStateRefreshesWithoutAutomaticallyEnabling()throws Exception{PipService.state(service).edit().putBoolean("busy",true).putBoolean("pending",false).commit();send(1,10123,true);assertEquals(PipService.REFRESH,Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService().getAction());}
 @Test public void busyAndMalformedRequestsDoNotQueueAnotherMutation()throws Exception{PipService.state(service).edit().putBoolean("busy",true).putBoolean("pending",true).commit();assertFalse(send(2,10123,false).getBoolean("accepted"));assertFalse(send(99,10123,false).getBoolean("accepted"));assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertTrue(send(1,10123,false).getBoolean("busy"));PipService.state(service).edit().putBoolean("busy",false).putBoolean("pending",false).putBoolean("rollback",true).commit();assertFalse(send(2,10123,false).getBoolean("accepted"));assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertTrue(send(3,10123,false).getBoolean("accepted"));assertEquals(PipService.DISABLE,Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService().getAction());}
}
